const mat=(T,c,extra={})=>new T.MeshStandardMaterial({color:c,roughness:.32,metalness:.03,...extra});
function ball(g,T,x,y,z,r,c,scale=[1,1,1],name=''){let m=new T.Mesh(new T.SphereGeometry(r,28,20),mat(T,c));m.position.set(x,y,z);m.scale.set(...scale);m.name=name;g.add(m);return m;}
function rod(g,T,a,b,r,c,name=''){let p=new T.Vector3(...a),q=new T.Vector3(...b),v=q.clone().sub(p),m=new T.Mesh(new T.CylinderGeometry(r,r,v.length(),16),mat(T,c));m.position.copy(p.add(q).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),v.normalize());m.name=name;g.add(m);return m;}
function virus(g,T,x,y,z,r=.38){ball(g,T,x,y,z,r,0xd29183,[1,1,1],'virus-core');for(let i=0;i<12;i++){let a=i*Math.PI*2/12;rod(g,T,[x+Math.cos(a)*r,y+Math.sin(a)*r,z],[x+Math.cos(a)*r*1.35,y+Math.sin(a)*r*1.35,z],r*.09,0xf0c3a2,'viral-spike');}}
function bacterium(g,T,x=0,y=0,s=1){let m=new T.Mesh(new T.CapsuleGeometry(.35*s,.85*s,12,28),mat(T,0x85b5b5));m.rotation.z=Math.PI/2;m.position.set(x,y,0);m.name='bacterial-cell';g.add(m);rod(g,T,[x-.4*s,y,.33*s],[x+.4*s,y,.33*s],.035*s,0xede0b8,'bacterial-DNA-symbol');for(let i=0;i<5;i++)rod(g,T,[x-.5*s+i*.25*s,y+.27*s,0],[x-.5*s+i*.25*s,y+.5*s,0],.025*s,0xc0d7cd);}
function cell(g,T){let membrane=new T.Mesh(new T.SphereGeometry(1.35,48,32,0,Math.PI*2,Math.PI*.28,Math.PI*.72),mat(T,0x8caeae,{side:T.DoubleSide}));membrane.rotation.x=Math.PI/2;membrane.name='open-host-membrane';g.add(membrane);ball(g,T,-.55,-.25,-.35,.33,0xa78caa,[1,1,.8],'host-nucleus');}
function arrow(g,T,x,y,angle=0){let a=new T.Mesh(new T.ConeGeometry(.16,.35,24),mat(T,0xf1b798));a.rotation.z=angle;a.position.set(x,y,.2);a.name='route-arrow';g.add(a);}
function leaf(g,T,state){if(state==='dropped'){rod(g,T,[0,-1.5,0],[0,1.3,0],.06,0x9aaa8b);return;}let shape=new T.Shape();shape.moveTo(0,-1.5);shape.bezierCurveTo(-2,.1,-1.1,1.4,0,1.6);shape.bezierCurveTo(1.1,1.4,2,.1,0,-1.5);let m=new T.Mesh(new T.ExtrudeGeometry(shape,{depth:.12,bevelEnabled:true,bevelSize:.035,bevelThickness:.035,bevelSegments:3}),mat(T,state==='blackspot'?0xc5bf8e:0x8fae9a));m.name='leaf-surface';g.add(m);rod(g,T,[0,-1.4,.2],[0,1.4,.2],.035,0xd8d4ab);for(let i=0;i<6;i++)for(let sign of[-1,1])rod(g,T,[0,-.9+i*.37,.2],[sign*(.7-Math.abs(i-3)*.08),-.6+i*.37,.2],.018,0xc2c9a5);if(['tmv','blackspot'].includes(state))for(let i=0;i<11;i++)ball(g,T,Math.sin(i*4)*.7,-.95+(i%6)*.37,.18,state==='tmv'?.18:.12,state==='tmv'?0xddce93:0x6c5865,[1,.8,.15],'disease-patch');}
export function buildInfection(g,T,w={}){const kind=w.kind||'types',s=w.state||'bacterium',reveal=w.revealed!==false;
 if(kind==='types'){if(s==='virus')virus(g,T,0,0,0,.85);else if(s==='bacterium')bacterium(g,T,0,0,1.5);else if(s==='fungus'){for(let i=-2;i<=2;i++){rod(g,T,[0,-1.35,0],[i*.48,.2,Math.abs(i)*.1],.085,0xd4b494,'fungal-hypha');rod(g,T,[i*.48,.2,Math.abs(i)*.1],[i*.6,1.1,0],.06,0xe3c9a8);ball(g,T,i*.6,1.1,0,.15,0xddc2a6);}}else{ball(g,T,0,0,0,1,0x9cafad,[1.35,.7,.65],'protist-cell');ball(g,T,-.35,0,.55,.23,0xa78caa);for(let i=0;i<20;i++){let a=i*Math.PI/10;rod(g,T,[Math.cos(a)*1.3,Math.sin(a)*.7,0],[Math.cos(a)*1.55,Math.sin(a)*.95,0],.02,0xc1d4c6);}}}
 else if(kind==='leaf')leaf(g,T,reveal?s:'healthy');
 else if(['replicate','host','virus','damage'].includes(kind)){cell(g,T);if(kind==='damage'&&s==='bacterium'){bacterium(g,T,-1.8,.3,.65);if(reveal)for(let i=0;i<5;i++)ball(g,T,-1.2+i*.28,.5,.55,.075,0xeac38f,[1,1,1],'toxin');}else{let n=reveal?(s==='copies'?9:s==='release'?12:1):1;for(let i=0;i<n;i++){let x=n===1?1.7:Math.sin(i*2.4)*.75,y=n===1?.1:Math.cos(i*2.4)*.75;if(s==='release'&&reveal&&i>6)x+=1.2;virus(g,T,x,y,.45,.16);}}}
 else if(kind==='susceptibility'||kind==='food'){let count=kind==='food'?(s==='hygiene'&&reveal?1:6):(s==='susceptible'&&reveal?0:6);for(let i=0;i<count;i++)bacterium(g,T,-1.2+(i%3)*1.2,-.65+Math.floor(i/3)*1.3,.52);for(let i=0;i<3;i++)ball(g,T,-1+i,.2,-.4,.15,0xe6c9a0,[1,.5,1],'intervention-marker');}
 else if(kind==='mosquito'){ball(g,T,0,0,0,.38,0xaf9b8f,[1,1.2,1],'thorax');ball(g,T,0,-.85,0,.4,0xc6a795,[.55,1.6,.65],'abdomen');ball(g,T,0,.65,0,.24,0xb2aaa1);rod(g,T,[0,.7,0],[.1,1.5,0],.035,0xd2c8bb,'proboscis');for(let sign of[-1,1]){let wing=ball(g,T,sign*.75,.1,-.1,.65,0xadc5c7,[1.5,.42,.08],'wing');wing.rotation.z=sign*.4;for(let i=0;i<3;i++){rod(g,T,[sign*.2,.1-i*.2,0],[sign*.9,.4-i*.4,0],.025,0xd0c4b5);rod(g,T,[sign*.9,.4-i*.4,0],[sign*1.7,.7-i*.65,0],.025,0xd0c4b5);}}if(s==='net'&&reveal)for(let i=-5;i<=5;i++){rod(g,T,[i*.35,-1.7,.75],[i*.35,1.7,.75],.012,0xd2e0d2,'net');rod(g,T,[-1.75,i*.3,.75],[1.75,i*.3,.75],.012,0xd2e0d2,'net');}if(s==='breeding'&&reveal){let m=new T.Mesh(new T.TorusGeometry(1.5,.045,10,60),mat(T,0xefab95));g.add(m);rod(g,T,[-1,-1,.9],[1,1,.9],.045,0xefab95,'breeding-control');}ball(g,T,.15,0,.4,.09,0xf0bb8e,[1,1,1],'protist-symbol');}
 else if(kind==='cilia'){for(let i=0;i<9;i++){let x=-1.6+i*.4;ball(g,T,x,-.65,0,.25,0x89a9ab,[.8,1.5,.8]);rod(g,T,[x,-.3,.1],[x+(s==='cleared'&&reveal?.2:0),.2,.1],.025,0xe2d2b0,'cilium');}for(let i=0;i<7;i++)ball(g,T,-1.4+i*.45+(s==='cleared'&&reveal?.4:0),.4,.1,.12,0xd79585,[1,1,1],'trapped-particle');arrow(g,T,1.6,.9,-Math.PI/2);}
 else if(kind==='phagocyte'){cell(g,T);if(s==='digest'&&reveal){for(let i=0;i<5;i++)ball(g,T,.25+(i%3)*.15,.2+(i%2)*.15,.45,.07,0xd9b393,[1,1,1],'digested-fragment');}else bacterium(g,T,s==='engulf'&&reveal?.4:1.8,.3,.48);}
 else if(kind==='antibody'){let toxin=s==='toxin';ball(g,T,.8,.25,0,.5,toxin?0xe3bd8e:0x8aadb0,[1,.8,.7],toxin?'toxin-target':'antigen-bearing-pathogen');let antigen=new T.Mesh(new T.BoxGeometry(.2,.2,.2),mat(T,0xf1c89f));antigen.position.set(.23,.3,.35);antigen.name='target-antigen-symbol';g.add(antigen);let offset=reveal&&s!=='wrong'?-.12:-.7;rod(g,T,[offset,-.8,.35],[offset,-.15,.35],.065,0xd99384,'antibody-stem');for(let sign of[-1,1])rod(g,T,[offset,-.15,.35],[offset+sign*.35,.3,.35],.065,0xd99384,'binding-arm');if(s==='wrong')ball(g,T,offset+.35,.3,.35,.13,0xe4c9a0,[1,1,1],'nonmatching-site');else{let m=new T.Mesh(new T.BoxGeometry(.2,.2,.2),mat(T,0xf1c89f));m.position.set(offset+.35,.3,.35);m.name='matching-site';g.add(m);}}
 else if(kind==='barrier'){if(s==='stomach'){let bowl=new T.Mesh(new T.SphereGeometry(1.2,48,32,0,Math.PI*2,0,Math.PI*.65),mat(T,0xc7a797,{side:T.DoubleSide}));bowl.rotation.x=Math.PI;bowl.name='stomach-cutaway';g.add(bowl);for(let i=0;i<14;i++)ball(g,T,Math.sin(i*2)*.75,-.4+Math.cos(i*2)*.15,.5,.08,0xf1d8a4,[1,1,1],'acid-symbol');virus(g,T,.7,.9,.3,.2);}else{for(let i=0;i<8;i++)ball(g,T,-1.5+i*.42,-.5,0,.3,0xa7b5ac,[.75,1,.6],'barrier-cell');if(s==='nose'){for(let i=0;i<9;i++)rod(g,T,[-1.5+i*.38,-.3,0],[-1.4+i*.38,.4,.1],.025,0xdac4a7,'nose-hair');for(let i=0;i<7;i++)ball(g,T,-1.2+i*.4,.4,.1,.12,0xb4ccc1,[1.3,.5,1],'mucus');}else{rod(g,T,[-.3,-.2,.2],[.35,-.2,.2],.12,0xa77f71,'scab');}for(let i=0;i<4;i++)virus(g,T,-1+i*.65,.75,.15,.11);}}
 else {for(let i=0;i<8;i++)ball(g,T,-1.5+i*.42,-.4,0,.3,0xa7b5ac,[.75,1,.6],'barrier-cell');let blocked=reveal&&['water','air','contact','barrier','measles','hiv','skin','nose','stomach'].includes(s);for(let i=0;i<4;i++)virus(g,T,-1.1+i*.6,blocked?.6:-.7,.2,.12);if(blocked)rod(g,T,[-1.8,.1,.3],[1.8,.1,.3],.055,0xe9c7a1,'interrupted-route');}
}
